import socket
import concurrent.futures
from typing import List, Tuple

def tcp_port_scan(target: str, start: int = 1, end: int = 1024, timeout: float = 0.5, threads: int = 100) -> List[Tuple[int, str]]:
    """Scan TCP ports on target. Returns list of (port, service_name) tuples."""
    open_ports = []

    def check_port(port: int) -> Tuple[int, str] | None:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(timeout)
                if s.connect_ex((target, port)) == 0:
                    try:
                        service = socket.getservbyport(port, 'tcp')
                    except OSError:
                        service = 'unknown'
                    return (port, service)
        except (socket.error, OSError):
            pass
        return None

    with concurrent.futures.ThreadPoolExecutor(max_workers=threads) as executor:
        futures = {executor.submit(check_port, p): p for p in range(start, end + 1)}
        for future in concurrent.futures.as_completed(futures):
            result = future.result()
            if result:
                open_ports.append(result)

    return sorted(open_ports, key=lambda x: x[0])
