def crack_md5(target_hash: str, wordlist_path: str) -> Optional[str]:
    """Crack an MD5 hash against a wordlist. Returns plaintext or None."""
    target_hash = target_hash.lower().strip()

    with open(wordlist_path, 'r', errors='ignore') as f:
        for line in f:
            candidate = line.strip()
            if hashlib.md5(candidate.encode()).hexdigest() == target_hash:
                return candidate
    return None

def crack_md5_batch(hash_file: str, wordlist_path: str) -> dict[str, str]:
    """Crack multiple MD5 hashes. Returns {hash: plaintext} dict."""
    targets = {}
    with open(hash_file) as f:
        for line in f:
            h = line.strip().lower()
            if len(h) == 32:  # Valid MD5 length
                targets[h] = None

    with open(wordlist_path, 'r', errors='ignore') as f:
        for line in f:
            candidate = line.strip()
            digest = hashlib.md5(candidate.encode()).hexdigest()
            if digest in targets and targets[digest] is None:
